class Solution {
    public ListNode oddEvenList(ListNode head){
        if(head==null||head.next==null)return head;
        ListNode odd=head,even=head.next,evenHead=even;
        while(even!=null&&even.next!=null){
            odd.next=even.next;
            odd=odd.next;
            even.next=odd.next;
            even=even.next;
        }
        odd.next=evenHead;
        return head;
    }
}

code.kotlin:
class Solution {
    fun oddEvenList(head:ListNode?):ListNode?{
        if(head?.next==null)return head;
        var odd=head;
        var even=head.next;
        val evenHead=even;
        while(even?.next!=null){
            odd!!.next=even.next;
            odd=odd.next;
            even.next=odd!!.next;
            even=even.next
        };
        odd!!.next=evenHead;
        return head
    }
}

